<?php
namespace R2Soft\Canvi\Webhook; use R2Soft\Canvi\Contracts\WebhookValidator; final class DefaultWebhookValidator implements WebhookValidator{ public function __construct(private readonly ?string $secret=null, private readonly string $header='X-Signature', private readonly string $algo='sha256'){} public function isValid(string $raw, ?string $sig): bool{ if(!$this->secret||!$sig)return false; return hash_equals(hash_hmac($this->algo,$raw,$this->secret),$sig);} public function isValidFromServer(array $s,string $raw):bool{ $k='HTTP_'.strtoupper(str_replace('-','_',$this->header)); return $this->isValid($raw,$s[$k]??null);} }